package app.justaguess.mobile;
public class ServerAddressTest {
 public static void main(String[] args){String[] allowed={"https://api.example.com","https://api.example.com/","http://192.168.1.10:8080","http://10.0.2.2:8080","http://172.16.0.8:8080","http://localhost:8080"};for(String value:allowed)if(ServerAddress.normalize(value,true)==null)throw new AssertionError("Expected accepted: "+value);String[] blocked={"http://api.example.com","http://10.evil.com","http://192.168.evil.com","http://172.32.0.1","http://999.168.1.10","https://user:pass@api.example.com","https://api.example.com/path","https://api.example.com?token=abc","javascript:alert(1)","file:///data/private","https://api.example.com#fragment"};for(String value:blocked)if(ServerAddress.normalize(value,true)!=null)throw new AssertionError("Expected rejected: "+value);if(ServerAddress.normalize("http://192.168.1.1",false)!=null)throw new AssertionError("Release must reject HTTP");System.out.println("18 Android server-address cases passed.");}
}
